const r="http://localhost:5000";chrome.runtime.onMessage.addListener((e,o)=>(e.type!=="LINK_CLICKED"||c(e.url,e.title).catch(n=>{console.warn("[Linker BG] handleLinkCapture failed:",n)}),!1));async function c(e,o){const n=await chrome.storage.local.get(["isTracking","token"]),i=n.isTracking,a=n.token;if(!i||!a)return;const t=await fetch(`${r}/api/links/extension`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${a}`},body:JSON.stringify({url:e,title:o})});if(!t.ok){const s=await t.json();console.warn("[Linker] Failed to save link:",s.message??t.statusText)}}
